   {"number": 3, "action_label": "Connect with J2Wite within 48 hours", "action_detail": "Understand intent. Listen only — do NOT influence decision.", "owner_role": "hrbp", "sla_working_hours": 48, "escalate_to_role": "ops_head", "email_template_id": null, "hard_gate": null, "kra_ref": "K2", "medium": "comment", "medium_config": {"instruction": "Connect with the consultant and listen to their intent. Do NOT influence the decision. Log the conversation summary below.", "placeholder": "Describe the conversation: consultant intent, concerns raised, sentiment, any retention signals..."}},
